SVG_PIECES = _json.loads(_zlib.decompress(_base64.b85decode(_PACKED_SVG)).decode('utf-8'))
del _PACKED_SVG

import base64
import re
import xml.etree.ElementTree as ET
from functools import lru_cache

@lru_cache(maxsize=228)
def _piece_image(theme, symbol):
    if theme == 'wood3d':
        from piece_3d import PIECE_PNGS
        return 'data:image/png;base64,' + PIECE_PNGS[symbol]
    key = theme + '/' + ('w' if symbol.isupper() else 'b') + symbol.upper()
    ET.register_namespace('', 'http://www.w3.org/2000/svg')
    ET.register_namespace('xlink', 'http://www.w3.org/1999/xlink')
    element = ET.fromstring(SVG_PIECES[key])
    if 'viewBox' not in element.attrib:
        def pixels(value):
            match = re.fullmatch(r'([0-9.]+)(px|pt|mm|cm|in)?', value)
            if match is None:
                raise ValueError('Unsupported SVG dimensions: ' + value)
            scale = {None:1, 'px':1, 'pt':96/72, 'mm':96/25.4, 'cm':96/2.54, 'in':96}[match[2]]
            return float(match[1]) * scale
        width = pixels(element.get('width', '45'))
        height = pixels(element.get('height', '45'))
        element.set('viewBox', f'0 0 {width:g} {height:g}')
    # Isolate each drawing so its CSS and gradient IDs cannot recolor other
    # pieces. The embedded image is still vector artwork rendered by CairoSVG.
    element.set('width', '90'); element.set('height', '90')
    element.set('preserveAspectRatio', 'xMidYMid meet')
    # Render every source separately. CairoSVG can otherwise reuse gradient
    # definitions incorrectly between repeated nested SVG images on a board.
    import cairosvg
    png = cairosvg.svg2png(bytestring=ET.tostring(element, encoding='utf-8'),
                          output_width=180, output_height=180)
    encoded = base64.b64encode(png).decode('ascii')
    return 'data:image/png;base64,' + encoded

def render_piece_overlay(board, orientation, theme):
    parts = ['<g class="illustrated-piece-set">']
    for square, piece in board.piece_map().items():
        file, rank = square % 8, square // 8
        x = 15 + 45 * (file if orientation else 7-file)
        y = 15 + 45 * (7-rank if orientation else rank)
        source = _piece_image(theme, piece.symbol())
        parts.append(f'<image xmlns:xlink="http://www.w3.org/1999/xlink" '
                     f'x="{x}" y="{y}" width="45" height="45" '
                     f'preserveAspectRatio="xMidYMid meet" xlink:href="{source}"/>')
    parts.append('</g>')
    return ''.join(parts)



