def render_twitch_piece_overlay(board, orientation):
    """Return a square-aligned SVG overlay using the approved Twitch sprites."""
    square_size = 45.0
    board_offset = 15.0

    # Tight-cropped sprites are sized by piece type, then bottom-aligned inside
    # each 45x45 square. This keeps every piece on its own square and preserves
    # natural online-chess proportions (pawns smaller, king/queen larger).
    heights = {
        "K": 43.0, "Q": 41.0, "R": 37.0, "B": 40.0, "N": 40.0, "P": 32.0,
        "k": 43.0, "q": 41.0, "r": 37.0, "b": 40.0, "n": 40.0, "p": 32.0,
    }
    source_sizes = {
        "K": (70, 93), "Q": (73, 87), "R": (77, 82), "B": (71, 89), "N": (81, 84), "P": (64, 78),
        "k": (72, 85), "q": (77, 88), "r": (78, 80), "b": (72, 87), "n": (84, 85), "p": (66, 78),
    }

    present = {piece.symbol() for piece in board.piece_map().values()}
    defs = ['<defs>']
    for symbol in sorted(present):
        payload = TWITCH_PIECE_PNG_BASE64.get(symbol)
        if not payload:
            continue
        sw, sh = source_sizes[symbol]
        safe = f"tw_{ord(symbol)}"
        defs.append(
            f'<image id="{safe}" width="{sw}" height="{sh}" '
            f'preserveAspectRatio="xMidYMid meet" '
            f'href="data:image/png;base64,{payload}"/>'
        )
    defs.append('</defs>')

    parts = ['<g class="twitch-piece-set">', ''.join(defs)]
    for square, piece in board.piece_map().items():
        file_index = square & 7
        rank_index = square >> 3
        square_x = (file_index if orientation else 7 - file_index) * square_size + board_offset
        square_y = (7 - rank_index if orientation else rank_index) * square_size + board_offset

        symbol = piece.symbol()
        sw, sh = source_sizes[symbol]
        target_h = heights[symbol]
        target_w = target_h * (sw / sh)

        # Center horizontally and sit on a shared baseline near the bottom
        # of the square, exactly like conventional 2D online piece sets.
        x = square_x + (square_size - target_w) / 2.0
        y = square_y + square_size - target_h - 1.0

        safe = f"tw_{ord(symbol)}"
        parts.append(
            f'<use href="#{safe}" x="{x:.2f}" y="{y:.2f}" '
            f'width="{target_w:.2f}" height="{target_h:.2f}"/>'
        )
    parts.append('</g>')
    return ''.join(parts)


if __name__ == '__main__':
    import argparse
    from pathlib import Path
    parser = argparse.ArgumentParser(description='Export the bundled original SVG drawings.')
    parser.add_argument('--export-svg', required=True, metavar='DIRECTORY')
    destination = Path(parser.parse_args().export_svg)
    for key, drawing in SVG_PIECES.items():
        target = destination / (key + '.svg')
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(drawing, encoding='utf-8')
    print(f'Exported {len(SVG_PIECES)} SVG drawings.')
